const schemes=['HMF-Audit','BLAS','DHT-backed','EVSEB'];
const queryDefaults={tenant:'T246',region:'R0',service:'spark-executor',logType:'INFO'};
const flowSchemes=()=>state.mode==='blas'?['BLAS','HMF-Audit','DHT-backed','EVSEB']:schemes;
const $=s=>document.querySelector(s);
const state={mode:'verify',active:null,history:[],target:null,status:null,events:[],rows:[],step:-1,trial:0,results:{}};
const escape=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const fmt=n=>Number.isFinite(Number(n))?`${Number(n).toFixed(Number(n)<10?2:0)} ms`:'—';
function rows(){const box=$('#scheme-rows');box.replaceChildren();schemes.forEach(name=>{const r=state.results[name]||{},stored=state.status?.storage?.[name]?.records,caption=r.message||(Number.isFinite(stored)?`${stored.toLocaleString()} records stored`:'Persistent proof store'),row=document.createElement('div');row.className='scheme-row';row.innerHTML=`<div><span class="scheme-name">${name}</span><span class="scheme-caption">${escape(caption)}</span></div><div class="bar"><div class="${String(r.status||'').toLowerCase()}" style="width:${['VALID','LOCALIZED','INGESTED','REJECTED'].includes(r.status)?100:r.status==='RUNNING'?Math.min(90,Math.max(12,(state.trial||1)*25)):0}%"></div></div><div class="scheme-outcome"><span class="status ${String(r.status||'').toLowerCase()}">${escape(r.status||'READY')}</span><span class="scheme-time">${fmt(r.ms)}</span></div>`;box.append(row)})}
function activity(){const list=$('#activity');list.replaceChildren();const events=state.active?.events||state.events;if(!events.length){list.innerHTML='<li class="empty">Start a workflow to watch live progress.</li>';return}for(const e of events.slice(-32).reverse()){const li=document.createElement('li');li.innerHTML=`<time>${new Date(e.time||Date.now()).toLocaleTimeString()}</time><span>${escape(e.message||e.type||'Progress')}</span>`;list.append(li)}}
function logRows(){const box=$('#log-rows');if(!state.rows.length){$('#logs-panel').hidden=true;return}$('#logs-panel').hidden=false;$('#log-count').textContent=`${state.rows.length} authenticated records`;box.replaceChildren();state.rows.slice(0,14).forEach(r=>{const row=document.createElement('div');row.className='log-row';row.innerHTML=`<code>${escape(r.id)}</code><span class="status ${String(r.status).toLowerCase()}">${escape(r.status)}</span>`;box.append(row)})}
function render(){const online=Boolean(state.status?.online);$('#connection').className=`connection ${online?'online':'offline'}`;$('#connection').innerHTML=`<span></span>${online?'Live Docker storage connected':'Live Docker storage unavailable'}`;const total=schemes.reduce((sum,name)=>sum+Number(state.status?.storage?.[name]?.records||0),0);$('#dataset-count').textContent=online?`${total.toLocaleString()} records in proof stores`:state.status?.dataset?'100,000 source records available':'Spark source missing';rows();activity();logRows();const target=state.target?.id;$('#case').hidden=!target;$('#case-id').textContent=target||'';$('#tamper-button').hidden=state.mode!=='localize'||Boolean(target);$('#localize-button').hidden=state.mode!=='localize'||!target;$('#restore-button').hidden=!target;$('#stop-button').hidden=!state.active||!['verify','verify-blas','localize'].includes(state.active.action);$('#stop-button').disabled=Boolean(state.stopping);$('#tamper-button').disabled=Boolean(state.active);$('#localize-button').disabled=Boolean(state.active);$('#restore-button').disabled=Boolean(state.active);$('#verify-button').disabled=Boolean(state.active);$('#ingest-button').disabled=Boolean(state.active);$('#flow-state').className=`flow-state ${state.active?'running':''}`;$('#flow-state').innerHTML=`<i></i> ${state.active?escape(state.active.action):'Ready'}`;draw()}
async function refresh(){try{state.status=await(await fetch('/api/status',{cache:'no-store'})).json();render()}catch{render()}}
async function loadQueryOptions(){try{const r=await fetch('/api/options',{cache:'no-store'});if(!r.ok)throw Error('Could not load dataset attributes.');const options=await r.json();for(const [field,values] of Object.entries(options)){const select=document.querySelector(`[data-query-option="${field}"]`);if(!select)continue;const preferred=queryDefaults[field];for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)}if(values.includes(preferred))select.value=preferred;else if(values.length)select.value=values[0]}}catch(error){$('#action-error').textContent=error.message;$('#action-error').hidden=false}}
function connect(){const es=new EventSource('/api/events');es.addEventListener('snapshot',e=>{const x=JSON.parse(e.data);state.active=x.active;state.history=x.history||[];state.target=x.target;render()});es.addEventListener('start',e=>{state.active=JSON.parse(e.data);state.events=[];state.results={};state.rows=[];state.step=-1;state.trial=0;state.stopping=false;render()});es.addEventListener('progress',e=>{const x=JSON.parse(e.data),v=x.event;state.active={...state.active,events:[...(state.active?.events||[]),v]};state.events=state.active.events;if(v.type==='scheme'){state.step=flowSchemes().indexOf(v.scheme);state.trial=0;state.results[v.scheme]={status:'RUNNING',message:v.message}}if(v.type==='trial'){state.trial=v.current;state.results[v.scheme]={status:'RUNNING',message:v.message}}if(v.type==='result')state.results[v.scheme]={status:v.status,ms:v.milliseconds,message:v.message};if(v.type==='batch')state.rows=v.rows||[];if(v.type==='tampered')state.target={id:v.id};if(v.type==='restored')state.target=null;render()});es.addEventListener('finish',e=>{const f=JSON.parse(e.data);if(f.cancelled){const scheme=flowSchemes()[state.step];if(scheme)state.results[scheme]={status:'STOPPED',message:'Stopped by user'}}state.active=null;state.stopping=false;state.target=f.target;refresh()});es.onerror=()=>{$('#connection').className='connection offline';$('#connection').innerHTML='<span></span> Reconnecting'}}
async function launch(action,extra={}){const f=new FormData($('#query-form')),query={tenant:String(f.get('tenant')||'').trim(),service:String(f.get('service')||'').trim(),logType:String(f.get('logType')||'').trim(),region:String(f.get('region')||'').trim(),start:String(f.get('start')||'').trim(),end:String(f.get('end')||'').trim()};$('#action-error').hidden=true;try{const r=await fetch('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,query,repeats:Number(f.get('repeats')||3),...extra})}),data=await r.json();if(!r.ok)throw Error(data.error);$('#queue').textContent='Workflow started'}catch(e){$('#action-error').textContent=e.message;$('#action-error').hidden=false}}
async function stopVerification(){if(!state.active)return;state.stopping=true;$('#stop-button').disabled=true;try{const r=await fetch('/api/stop',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:state.active.id})}),data=await r.json();if(!r.ok)throw Error(data.error);$('#queue').textContent='Stopping verification…'}catch(e){state.stopping=false;$('#action-error').textContent=e.message;$('#action-error').hidden=false;render()}}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;document.querySelectorAll('.tab').forEach(t=>{t.classList.toggle('selected',t===b);t.setAttribute('aria-pressed',String(t===b))});$('#query-form').hidden=state.mode==='ingest';$('#verify-controls').hidden=!['verify','blas'].includes(state.mode);$('#localize-controls').hidden=state.mode!=='localize';$('#ingest-form').hidden=state.mode!=='ingest';$('#flow-heading').textContent={verify:'Verification path',blas:'BLAS sourced verification',localize:'Tamper localization',ingest:'Ingestion'}[state.mode];$('#flow-description').textContent={verify:'Authenticate the ALL query and verify the matching logs.',blas:'BLAS resolves the query, publishes its log IDs, then the other schemes verify that batch.',localize:'Find the altered leaf against the anchored root.',ingest:'Stream the real Spark records into each proof store.'}[state.mode];render()});
$('#query-form').onsubmit=e=>{e.preventDefault();launch(state.mode==='blas'?'verify-blas':'verify')};$('#tamper-button').onclick=()=>launch('tamper');$('#localize-button').onclick=()=>launch('localize',{repeats:Number(new FormData($('#query-form')).get('repeats')||3)});$('#restore-button').onclick=()=>launch('restore');$('#stop-button').onclick=stopVerification;$('#ingest-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);launch('ingest',{selection:f.get('selection'),replace:f.get('replace')==='on'})};
function draw(){const c=$('#diagram'),ctx=c?.getContext('2d');if(!ctx)return;const r=c.getBoundingClientRect(),d=window.devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;ctx.scale(d,d);const w=r.width,h=r.height,g=w/5,y=h/2;ctx.clearRect(0,0,w,h);for(let i=0;i<3;i++){ctx.strokeStyle=i<state.step?'#86ebbd':'#365b4c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(g*(i+1)+14,y);ctx.lineTo(g*(i+2)-14,y);ctx.stroke()}for(let i=0;i<4;i++){const x=g*(i+1),on=i===state.step;ctx.beginPath();ctx.arc(x,y,on?17:11,0,Math.PI*2);ctx.fillStyle=i<state.step?'#5bd9a3':on?'#a1f6d0':'#294a3d';ctx.fill();if(on&&state.active){ctx.beginPath();ctx.arc(x,y,24+Math.sin(Date.now()/260)*4,0,Math.PI*2);ctx.strokeStyle='#87edbd88';ctx.stroke()}}if(state.active)requestAnimationFrame(draw)}
connect();refresh();loadQueryOptions();setInterval(refresh,5000);window.addEventListener('resize',draw);
